import{_ as i,I as d,o as l,c as o,b6 as a,J as s}from"./chunks/framework.COUcLbTA.js";const m=JSON.parse('{"title":"神经网络与深度学习","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/8-artificial-intelligence/neural-networks.md","filePath":"zh-cn/appendix/8-artificial-intelligence/neural-networks.md"}'),h={name:"zh-cn/appendix/8-artificial-intelligence/neural-networks.md"};function p(c,t,b,g,u,k){const e=d("NeuronDemo"),n=d("NetworkLayersDemo"),r=d("NetworkArchitectureDemo");return l(),o("div",null,[t[0]||(t[0]=a(`<h1 id="神经网络与深度学习" tabindex="-1">神经网络与深度学习 <a class="header-anchor" href="#神经网络与深度学习" aria-label="Permalink to “神经网络与深度学习”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>神经网络是 AI 革命的引擎。</strong> 从 ChatGPT 的语言理解到自动驾驶的图像识别，背后都是神经网络在工作。它不是魔法，而是一套精巧的数学框架——通过大量数据&quot;学习&quot;出输入到输出的映射关系。理解它的基本原理，能帮你更好地使用和调试 AI 工具。</p></div><p><strong>这篇文章会带你学什么？</strong></p><p>学完这章后，你将获得：</p><ul><li><strong>核心概念</strong>：理解神经元、层、前向传播、反向传播的基本原理</li><li><strong>网络类型</strong>：了解 CNN、RNN、Transformer 等主流架构的特点和适用场景</li><li><strong>训练过程</strong>：明白模型是如何从数据中&quot;学习&quot;的</li><li><strong>关键技巧</strong>：掌握过拟合、学习率、正则化等实用概念</li><li><strong>发展脉络</strong>：了解从感知机到大语言模型的演进历程</li></ul><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>从神经元到网络</td><td>感知机、激活函数、前向传播</td></tr><tr><td><strong>第 2 章</strong></td><td>网络如何学习</td><td>损失函数、梯度下降、反向传播</td></tr><tr><td><strong>第 3 章</strong></td><td>主流网络架构</td><td>CNN、RNN、Transformer</td></tr><tr><td><strong>第 4 章</strong></td><td>训练的艺术</td><td>过拟合、正则化、超参数调优</td></tr><tr><td><strong>第 5 章</strong></td><td>发展历程与前沿</td><td>从感知机到 GPT</td></tr></tbody></table><hr><h2 id="_1-从神经元到网络" tabindex="-1">1. 从神经元到网络 <a class="header-anchor" href="#_1-从神经元到网络" aria-label="Permalink to “1. 从神经元到网络”">​</a></h2><h3 id="单个神经元" tabindex="-1">单个神经元 <a class="header-anchor" href="#单个神经元" aria-label="Permalink to “单个神经元”">​</a></h3><p>神经网络的最小单元是<strong>神经元</strong>（Neuron）。它模拟了生物神经元的工作方式：接收多个输入信号，加权求和，通过激活函数产生输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>输入 x1 ──→ ×w1 ──┐</span></span>
<span class="line"><span>输入 x2 ──→ ×w2 ──┼──→ Σ(加权求和) + b(偏置) ──→ f(激活函数) ──→ 输出</span></span>
<span class="line"><span>输入 x3 ──→ ×w3 ──┘</span></span></code></pre></div><p>数学表达：<strong>y = f(w₁x₁ + w₂x₂ + w₃x₃ + b)</strong></p>`,12)),s(e),t[1]||(t[1]=a(`<h3 id="激活函数-为什么需要非线性" tabindex="-1">激活函数：为什么需要非线性？ <a class="header-anchor" href="#激活函数-为什么需要非线性" aria-label="Permalink to “激活函数：为什么需要非线性？”">​</a></h3><p>如果没有激活函数，无论多少层神经元叠加，最终都等价于一个线性变换（矩阵乘法）。激活函数引入<strong>非线性</strong>，让网络能学习复杂的模式。</p><table tabindex="0"><thead><tr><th>激活函数</th><th>公式</th><th>特点</th><th>常用场景</th></tr></thead><tbody><tr><td>ReLU</td><td>max(0, x)</td><td>简单高效，训练快</td><td>隐藏层的默认选择</td></tr><tr><td>Sigmoid</td><td>1/(1+e⁻ˣ)</td><td>输出 0~1</td><td>二分类输出层</td></tr><tr><td>Tanh</td><td>(eˣ-e⁻ˣ)/(eˣ+e⁻ˣ)</td><td>输出 -1~1</td><td>RNN 中常用</td></tr><tr><td>Softmax</td><td>eˣᵢ/Σeˣⱼ</td><td>输出概率分布</td><td>多分类输出层</td></tr></tbody></table><h3 id="从神经元到网络" tabindex="-1">从神经元到网络 <a class="header-anchor" href="#从神经元到网络" aria-label="Permalink to “从神经元到网络”">​</a></h3><p>把多个神经元组织成<strong>层</strong>，多个层串联起来，就构成了神经网络：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>输入层          隐藏层1        隐藏层2        输出层</span></span>
<span class="line"><span>(特征)         (提取低级特征)   (提取高级特征)   (预测结果)</span></span>
<span class="line"><span></span></span>
<span class="line"><span> x1 ──→  [○ ○ ○ ○] ──→ [○ ○ ○] ──→  [○ ○]</span></span>
<span class="line"><span> x2 ──→  [○ ○ ○ ○] ──→ [○ ○ ○] ──→  猫/狗</span></span>
<span class="line"><span> x3 ──→  [○ ○ ○ ○] ──→ [○ ○ ○]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>输入层</td><td>接收原始数据（图片像素、文本向量等）</td></tr><tr><td>隐藏层</td><td>中间处理层，层数越多网络越&quot;深&quot;（深度学习的&quot;深&quot;）</td></tr><tr><td>输出层</td><td>产生最终预测（分类概率、回归值等）</td></tr><tr><td>前向传播</td><td>数据从输入层逐层流向输出层的过程</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么叫&quot;深度&quot;学习？</p><p>传统机器学习通常只有 1-2 层。当隐藏层数量增加到几十甚至上百层时，就叫&quot;深度&quot;学习。更深的网络能学习更抽象的特征：第一层学边缘，第二层学纹理，第三层学部件，更深的层学到&quot;这是一只猫&quot;。</p></div><hr><h2 id="_2-网络如何学习" tabindex="-1">2. 网络如何学习 <a class="header-anchor" href="#_2-网络如何学习" aria-label="Permalink to “2. 网络如何学习”">​</a></h2><p>神经网络的&quot;学习&quot;本质上是一个<strong>优化问题</strong>：找到一组权重（w）和偏置（b），使得网络的预测尽可能接近真实答案。</p><h3 id="训练三步曲" tabindex="-1">训练三步曲 <a class="header-anchor" href="#训练三步曲" aria-label="Permalink to “训练三步曲”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 前向传播：输入数据，得到预测结果</span></span>
<span class="line"><span>2. 计算损失：用损失函数衡量预测与真实值的差距</span></span>
<span class="line"><span>3. 反向传播：根据损失，计算每个权重的梯度，更新权重</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>重复以上步骤，直到损失足够小</span></span></code></pre></div><h3 id="损失函数-衡量-错得有多离谱" tabindex="-1">损失函数：衡量&quot;错得有多离谱&quot; <a class="header-anchor" href="#损失函数-衡量-错得有多离谱" aria-label="Permalink to “损失函数：衡量&quot;错得有多离谱&quot;”">​</a></h3><p>损失函数（Loss Function）量化了预测值和真实值之间的差距。训练的目标就是最小化损失。</p><table tabindex="0"><thead><tr><th>损失函数</th><th>公式简述</th><th>适用场景</th></tr></thead><tbody><tr><td>MSE（均方误差）</td><td>预测值与真实值差的平方的均值</td><td>回归问题</td></tr><tr><td>Cross-Entropy（交叉熵）</td><td>-Σ y·log(ŷ)</td><td>分类问题</td></tr><tr><td>Binary Cross-Entropy</td><td>交叉熵的二分类版本</td><td>二分类问题</td></tr></tbody></table><h3 id="梯度下降-找到最低点" tabindex="-1">梯度下降：找到最低点 <a class="header-anchor" href="#梯度下降-找到最低点" aria-label="Permalink to “梯度下降：找到最低点”">​</a></h3><p>想象你站在一座山上，蒙着眼睛要走到最低点。你能做的就是<strong>摸一下脚下的坡度，然后往下坡方向走一步</strong>。这就是梯度下降。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>损失值</span></span>
<span class="line"><span>  ↑</span></span>
<span class="line"><span>  │    ╱╲</span></span>
<span class="line"><span>  │   ╱  ╲      ← 当前位置</span></span>
<span class="line"><span>  │  ╱    ╲    ↙ 沿梯度方向下降</span></span>
<span class="line"><span>  │ ╱      ╲╱   ← 局部最小值</span></span>
<span class="line"><span>  │╱            ╲╱  ← 全局最小值</span></span>
<span class="line"><span>  └──────────────→ 权重值</span></span></code></pre></div><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>梯度</td><td>损失函数对每个权重的偏导数，指示&quot;往哪个方向调整能减少损失&quot;</td></tr><tr><td>学习率</td><td>每一步走多远。太大会跳过最低点，太小会收敛太慢</td></tr><tr><td>批量大小</td><td>每次用多少样本计算梯度。全量太慢，单样本太抖，小批量（mini-batch）是折中</td></tr></tbody></table><h3 id="反向传播-链式法则的胜利" tabindex="-1">反向传播：链式法则的胜利 <a class="header-anchor" href="#反向传播-链式法则的胜利" aria-label="Permalink to “反向传播：链式法则的胜利”">​</a></h3><p>反向传播（Backpropagation）是计算梯度的高效算法。它利用微积分的<strong>链式法则</strong>，从输出层开始，逐层向后计算每个权重对损失的贡献。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>前向传播：输入 → 隐藏层1 → 隐藏层2 → 输出 → 损失</span></span>
<span class="line"><span>反向传播：损失 → 输出 → 隐藏层2 → 隐藏层1 → 更新所有权重</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">直觉理解反向传播</p><p>把神经网络想象成一条流水线。产品（预测）出了问题（损失大），你需要从最后一道工序开始往回查，看每道工序（每层权重）对最终问题贡献了多少，然后按贡献大小调整。贡献大的多调，贡献小的少调。</p></div><hr><h2 id="_3-主流网络架构" tabindex="-1">3. 主流网络架构 <a class="header-anchor" href="#_3-主流网络架构" aria-label="Permalink to “3. 主流网络架构”">​</a></h2><p>不同类型的数据需要不同的网络架构。选对架构，事半功倍。</p>`,27)),s(n),t[2]||(t[2]=a(`<h3 id="_3-1-cnn-卷积神经网络" tabindex="-1">3.1 CNN（卷积神经网络） <a class="header-anchor" href="#_3-1-cnn-卷积神经网络" aria-label="Permalink to “3.1 CNN（卷积神经网络）”">​</a></h3><p>CNN 是处理图像的王者。核心思想：用小的卷积核在图像上滑动，提取局部特征。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>输入图像 → [卷积层→激活→池化] × N → 全连接层 → 输出</span></span>
<span class="line"><span>  28×28      提取边缘/纹理/形状        分类结果</span></span></code></pre></div><table tabindex="0"><thead><tr><th>特点</th><th>说明</th></tr></thead><tbody><tr><td>局部连接</td><td>每个神经元只看一小块区域，而非整张图</td></tr><tr><td>参数共享</td><td>同一个卷积核在整张图上复用，大幅减少参数</td></tr><tr><td>平移不变性</td><td>猫在图片左边还是右边，都能识别</td></tr><tr><td>层级特征</td><td>浅层学边缘，深层学语义</td></tr></tbody></table><p>代表模型：LeNet、AlexNet、VGG、ResNet、EfficientNet</p><h3 id="_3-2-rnn-循环神经网络" tabindex="-1">3.2 RNN（循环神经网络） <a class="header-anchor" href="#_3-2-rnn-循环神经网络" aria-label="Permalink to “3.2 RNN（循环神经网络）”">​</a></h3><p>RNN 专为<strong>序列数据</strong>设计。它的隐藏状态会传递到下一个时间步，让网络具有&quot;记忆&quot;能力。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>时间步 t1    时间步 t2    时间步 t3</span></span>
<span class="line"><span> &quot;我&quot;  ──→   &quot;喜欢&quot;  ──→  &quot;猫&quot;</span></span>
<span class="line"><span>  ↓           ↓           ↓</span></span>
<span class="line"><span> [h1]  ──→  [h2]   ──→  [h3] ──→ 输出</span></span>
<span class="line"><span>  ↑           ↑           ↑</span></span>
<span class="line"><span> 隐藏状态在时间步之间传递（记忆）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>变体</th><th>解决的问题</th><th>核心机制</th></tr></thead><tbody><tr><td>原始 RNN</td><td>基础序列建模</td><td>简单循环连接</td></tr><tr><td>LSTM</td><td>长序列梯度消失</td><td>遗忘门、输入门、输出门</td></tr><tr><td>GRU</td><td>LSTM 参数太多</td><td>简化为重置门和更新门</td></tr><tr><td>双向 RNN</td><td>只能看到过去</td><td>同时从前往后和从后往前处理</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">LSTM 的门控机制</p><p>LSTM 的精妙之处在于三个&quot;门&quot;：<strong>遗忘门</strong>决定丢弃哪些旧记忆，<strong>输入门</strong>决定存入哪些新信息，<strong>输出门</strong>决定输出哪些内容。就像你读一本书，会选择性地记住重要情节、忘掉无关细节。</p></div><h3 id="_3-3-transformer-注意力就是一切" tabindex="-1">3.3 Transformer：注意力就是一切 <a class="header-anchor" href="#_3-3-transformer-注意力就是一切" aria-label="Permalink to “3.3 Transformer：注意力就是一切”">​</a></h3><p>2017 年 Google 发表的 &quot;Attention Is All You Need&quot; 论文提出了 Transformer，彻底改变了 AI 领域。它用<strong>自注意力机制</strong>替代了循环结构，是 GPT、BERT、Claude 等大模型的基础。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>输入序列 → 嵌入 + 位置编码 → [多头注意力 → 前馈网络] × N → 输出</span></span>
<span class="line"><span>                                    ↑</span></span>
<span class="line"><span>                          每个词都能&quot;看到&quot;所有其他词</span></span></code></pre></div><table tabindex="0"><thead><tr><th>优势</th><th>说明</th></tr></thead><tbody><tr><td>并行计算</td><td>不像 RNN 必须逐步处理，Transformer 可以并行处理整个序列</td></tr><tr><td>长距离依赖</td><td>任意两个位置之间直接建立联系，不受距离限制</td></tr><tr><td>可扩展性</td><td>模型越大、数据越多，效果越好（Scaling Law）</td></tr></tbody></table><p><strong>自注意力的直觉</strong>：读&quot;小猫坐在垫子上，因为<strong>它</strong>很累&quot;这句话时，&quot;它&quot;需要关注&quot;小猫&quot;才能理解含义。自注意力让模型学会这种关联——为序列中的每对词计算一个&quot;相关性分数&quot;。</p>`,15)),s(r),t[3]||(t[3]=a(`<h2 id="_4-训练的艺术" tabindex="-1">4. 训练的艺术 <a class="header-anchor" href="#_4-训练的艺术" aria-label="Permalink to “4. 训练的艺术”">​</a></h2><p>有了好的架构还不够，训练过程中有很多&quot;坑&quot;需要避开。</p><h3 id="_4-1-过拟合-vs-欠拟合" tabindex="-1">4.1 过拟合 vs 欠拟合 <a class="header-anchor" href="#_4-1-过拟合-vs-欠拟合" aria-label="Permalink to “4.1 过拟合 vs 欠拟合”">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>表现</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td>过拟合</td><td>训练集表现好，测试集表现差</td><td>模型太复杂，&quot;背答案&quot;而非学规律</td><td>正则化、Dropout、数据增强、早停</td></tr><tr><td>欠拟合</td><td>训练集和测试集都表现差</td><td>模型太简单，学不到规律</td><td>增加模型容量、训练更久、更好的特征</td></tr></tbody></table><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>误差</span></span>
<span class="line"><span>  ↑</span></span>
<span class="line"><span>  │ ╲  训练误差          测试误差  ╱</span></span>
<span class="line"><span>  │  ╲                          ╱</span></span>
<span class="line"><span>  │   ╲─────────────────╱</span></span>
<span class="line"><span>  │    欠拟合 ← 最佳点 → 过拟合</span></span>
<span class="line"><span>  └──────────────────────────→ 模型复杂度</span></span></code></pre></div><h3 id="_4-2-关键超参数" tabindex="-1">4.2 关键超参数 <a class="header-anchor" href="#_4-2-关键超参数" aria-label="Permalink to “4.2 关键超参数”">​</a></h3><p>超参数是训练前需要人为设定的参数（不是模型自己学的）：</p><table tabindex="0"><thead><tr><th>超参数</th><th>作用</th><th>常见范围</th><th>调优建议</th></tr></thead><tbody><tr><td>学习率</td><td>每步更新的幅度</td><td>1e-5 ~ 1e-1</td><td>最重要的超参数，通常从 1e-3 开始</td></tr><tr><td>批量大小</td><td>每次训练用多少样本</td><td>16 ~ 512</td><td>越大训练越稳定，但需要更多显存</td></tr><tr><td>训练轮数（Epoch）</td><td>遍历整个数据集的次数</td><td>10 ~ 100+</td><td>配合早停法，验证集不再提升就停</td></tr><tr><td>优化器</td><td>梯度更新策略</td><td>Adam、SGD</td><td>Adam 是默认选择，SGD+动量适合精调</td></tr></tbody></table><h3 id="_4-3-正则化技巧" tabindex="-1">4.3 正则化技巧 <a class="header-anchor" href="#_4-3-正则化技巧" aria-label="Permalink to “4.3 正则化技巧”">​</a></h3><p>防止过拟合的常用手段：</p><table tabindex="0"><thead><tr><th>技巧</th><th>原理</th><th>使用方式</th></tr></thead><tbody><tr><td>Dropout</td><td>训练时随机关闭部分神经元</td><td>通常 p=0.1~0.5</td></tr><tr><td>权重衰减</td><td>在损失函数中加入权重大小的惩罚</td><td>L2 正则化，λ=1e-4</td></tr><tr><td>数据增强</td><td>对训练数据做随机变换（翻转、裁剪、旋转）</td><td>图像任务必备</td></tr><tr><td>早停法</td><td>验证集损失不再下降时停止训练</td><td>patience=5~10</td></tr><tr><td>Batch Normalization</td><td>标准化每层的输入分布</td><td>加速收敛，有轻微正则化效果</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">训练的经验法则</p><ol><li>先用小数据集跑通整个流程，确认代码没 bug</li><li>从已有的预训练模型开始微调，而非从零训练</li><li>学习率是最值得花时间调的超参数</li><li>如果训练损失不下降，先检查数据和代码，再怀疑模型</li></ol></div><hr><h2 id="_5-发展历程与前沿" tabindex="-1">5. 发展历程与前沿 <a class="header-anchor" href="#_5-发展历程与前沿" aria-label="Permalink to “5. 发展历程与前沿”">​</a></h2><p>神经网络的发展经历了几次&quot;寒冬&quot;和&quot;复兴&quot;，每次突破都源于关键的技术创新。</p><table tabindex="0"><thead><tr><th>年代</th><th>里程碑</th><th>关键突破</th></tr></thead><tbody><tr><td>1958</td><td>感知机（Perceptron）</td><td>第一个神经网络模型，只能处理线性问题</td></tr><tr><td>1986</td><td>反向传播算法</td><td>让多层网络的训练成为可能</td></tr><tr><td>1998</td><td>LeNet（CNN）</td><td>卷积网络在手写数字识别上大获成功</td></tr><tr><td>2012</td><td>AlexNet</td><td>深度 CNN 在 ImageNet 上碾压传统方法，深度学习爆发</td></tr><tr><td>2014</td><td>GAN（生成对抗网络）</td><td>两个网络对抗训练，能生成逼真图像</td></tr><tr><td>2017</td><td>Transformer</td><td>&quot;Attention Is All You Need&quot;，注意力机制取代 RNN</td></tr><tr><td>2018</td><td>BERT</td><td>预训练+微调范式，NLP 全面突破</td></tr><tr><td>2020</td><td>GPT-3</td><td>1750 亿参数，展示了大模型的涌现能力</td></tr><tr><td>2022</td><td>ChatGPT</td><td>RLHF 对齐技术，AI 进入大众视野</td></tr><tr><td>2023+</td><td>多模态大模型</td><td>GPT-4V、Claude 等，同时理解文本和图像</td></tr></tbody></table><h3 id="当前趋势" tabindex="-1">当前趋势 <a class="header-anchor" href="#当前趋势" aria-label="Permalink to “当前趋势”">​</a></h3><table tabindex="0"><thead><tr><th>方向</th><th>说明</th></tr></thead><tbody><tr><td>大模型（LLM）</td><td>参数量从亿级到万亿级，涌现出推理、编程等能力</td></tr><tr><td>多模态</td><td>同一个模型处理文本、图像、音频、视频</td></tr><tr><td>高效微调</td><td>LoRA、QLoRA 等技术让普通开发者也能微调大模型</td></tr><tr><td>AI Agent</td><td>让大模型使用工具、规划任务、自主完成复杂目标</td></tr><tr><td>小模型蒸馏</td><td>用大模型的知识训练小模型，在端侧部署</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">对开发者的启示</p><p>你不需要从零训练神经网络。现代 AI 开发更多是<strong>调用 API</strong>（如 OpenAI、Claude API）或<strong>微调预训练模型</strong>（如用 Hugging Face）。但理解底层原理能帮你更好地选择模型、设计 prompt、诊断问题。</p></div><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><table tabindex="0"><thead><tr><th>核心概念</th><th>一句话总结</th></tr></thead><tbody><tr><td>神经元</td><td>加权求和 + 激活函数，网络的最小计算单元</td></tr><tr><td>前向传播</td><td>数据从输入层逐层流向输出层，产生预测</td></tr><tr><td>反向传播</td><td>从损失出发，逐层计算梯度，更新权重</td></tr><tr><td>CNN</td><td>卷积核提取局部特征，图像处理的首选</td></tr><tr><td>RNN/LSTM</td><td>循环连接保持记忆，处理序列数据</td></tr><tr><td>Transformer</td><td>自注意力并行处理，大模型的基础架构</td></tr><tr><td>过拟合</td><td>模型&quot;背答案&quot;，用正则化、Dropout 等手段防止</td></tr><tr><td>迁移学习</td><td>站在巨人肩膀上，用预训练模型微调解决新问题</td></tr></tbody></table><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><a href="https://www.3blue1brown.com/topics/neural-networks" target="_blank" rel="noreferrer">3Blue1Brown - 神经网络系列视频</a> — 最直观的可视化讲解</li><li><a href="http://cs231n.stanford.edu/" target="_blank" rel="noreferrer">Stanford CS231n</a> — 经典的卷积神经网络课程</li><li><a href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noreferrer">The Illustrated Transformer</a> — 图解 Transformer 架构</li><li><a href="http://neuralnetworksanddeeplearning.com/" target="_blank" rel="noreferrer">Neural Networks and Deep Learning</a> — 免费在线教材</li><li><a href="https://huggingface.co/learn" target="_blank" rel="noreferrer">Hugging Face 课程</a> — 动手实践 Transformer 和大模型</li></ul>`,25))])}const _=i(h,[["render",p]]);export{m as __pageData,_ as default};
